WHERE SBJ.DELYN = 'N'

  AND CHRT.ORG_ID = #{orgId}


  AND CHRT.DGRS_YR = #{haksaYear}


  AND CHRT.DGRS_SMSTR_CHRT = #{haksaTerm}


  AND SBJ.CRS_GBNCD = #{crsGbncd}


  AND SBJ.SBJCT_TYCD = #{sbjctTycd}


  AND SBJ.SBJCT_ID = #{sbjctId}


  AND SBJ.SBJCT_TYCD IN

    #{item}



  AND (
      LOWER(TO_CHAR(SBJ.CRCLMN_NO)) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
   OR LOWER(SBJ.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
   OR LOWER(NVL(PROF.USERNM, SBJ.PROF_ID)) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
   OR LOWER(NVL(SBJCT_ADM.TUT_USERNM, '-')) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
  )

WHERE SBJ.DELYN = 'N'

  AND CHRT.ORG_ID = #{orgId}


  AND CHRT.DGRS_YR = #{dgrsYr}


  AND CHRT.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}


  AND SBJ.CRS_GBNCD = #{crsGbncd}


  AND SBJ.SBJCT_TYCD = #{sbjctTycd}


  AND SBJ.SBJCT_ID = #{sbjctId}


  AND (
      LOWER(TO_CHAR(SBJ.CRCLMN_NO)) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
   OR LOWER(SBJ.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
   OR LOWER(NVL(PROF.USERNM, SBJ.PROF_ID)) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
   OR LOWER(NVL(SBJCT_ADM.TUT_USERNM, '-')) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
  )

mapper.update:
UPDATE TB_LMS_SBJCT
   SET RVW_PSBL_GBNCD = #{reviewStatus}
     , RVW_SDTTM = CASE WHEN #{reviewStatus} = 'PRD_STNG' THEN #{reviewStartDttm} ELSE NULL END
     , RVW_EDTTM = CASE WHEN #{reviewStatus} = 'PRD_STNG' THEN #{reviewEndDttm} ELSE NULL END
     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE SBJCT_ID = #{sbjctId}

   AND SMSTR_CHRT_ID IN (
       SELECT SMSTR_CHRT_ID
         FROM TB_LMS_SMSTR_CHRT
        WHERE ORG_ID = #{orgId}
   )
